import * as THREE from 'three';
import { AudioManager } from './assets/AudioManager';
import { registerAudioManifest } from './assets/audioManifest';
import { GAME_CONFIG } from './config/GameConfig';
import { applyQuality, volumeToGain } from './core/QualitySettings';
import { Renderer } from './core/Renderer';
import { resolveCourseSelection } from './courses';
import { parseLaunchOptions } from './dev/LaunchOptions';
import { Game } from './game/Game';
import { InputManager } from './input';
import './style.css';
import { AppUI, LoadingOverlay } from './ui';
import type { SetupDTO, UISettings } from './ui';

const root = document.querySelector<HTMLDivElement>('#app');
if (!root) throw new Error('Missing #app bootstrap element');
document.title = GAME_CONFIG.title;

// `?course=` and `?hole=` pick where the session starts; the registry resolves
// the request to a real course so the menu selector and deep links agree.
const launch = parseLaunchOptions(window.location.search);
const selection = resolveCourseSelection(launch);
document.documentElement.dataset.course = selection.course.id;
document.documentElement.dataset.hole = String(selection.holeNumber);

let settings: UISettings = { controlScheme: 'hold-to-charge', quality: 'high', volume: 80, reducedMotion: false };

// core/Renderer owns the WebGL state and survives a lost context; recovery resets
// renderer state, so the quality preset has to be pushed in again afterwards.
const renderer = new Renderer();
renderer.setSize(window.innerWidth, window.innerHeight);
applyQuality(renderer, settings.quality);
renderer.onContextRestored(() => applyQuality(renderer, settings.quality));
root.append(renderer.canvas);

/** Web Audio is optional: without it the match simply runs silent. */
function createMixer(): AudioManager | undefined {
  try {
    const mixer = new AudioManager();
    mixer.setMasterVolume(volumeToGain(settings.volume));
    void registerAudioManifest(mixer).then((events) => (events.length > 0 ? mixer.loadAll() : undefined));
    return mixer;
  } catch (error) {
    console.warn('Audio is unavailable; the match will run without sound', error);
    return undefined;
  }
}

const audio = createMixer();

const menuScene = new THREE.Scene();
menuScene.background = new THREE.Color(0x0b1622);
const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 400);
camera.position.set(0, 3, 8);
const input = new InputManager({ pointerTarget: renderer.canvas });

const gameLayer = document.createElement('div');
gameLayer.className = 'cpa-game';
root.append(gameLayer);
const menuLayer = document.createElement('div');
menuLayer.className = 'cpa-layer';
root.append(menuLayer);

const loading = new LoadingOverlay();
let game: Game | undefined;
let diagnostics: { frame(): void; dispose(): void } | undefined;
let starting = false;

function endMatch(): void {
  game?.dispose();
  game = undefined;
  menuLayer.hidden = false;
}

async function startMatch(setup: SetupDTO, startHoleIndex = 0): Promise<void> {
  if (game || starting) return;
  starting = true;
  menuLayer.hidden = true;
  gameLayer.append(loading.element);
  loading.render(0.2, 'Starting the physics engine…');
  try {
    game = await Game.create({
      renderer: renderer.renderer,
      camera,
      input,
      overlayRoot: gameLayer,
      courseId: setup.courseId,
      holeCount: setup.holes,
      humanCount: setup.players,
      botCount: setup.bots,
      controlScheme: settings.controlScheme,
      quality: settings.quality,
      volume: settings.volume,
      audio,
      startHoleIndex,
      onExit: endMatch,
    });
    loading.render(1, 'Ready');
  } catch (error) {
    console.error('Failed to start the match', error);
    menuLayer.hidden = false;
  } finally {
    starting = false;
    loading.element.remove();
  }
}

new AppUI(
  menuLayer,
  {
    startMatch: (_mode, setup) => {
      void startMatch(setup);
    },
    saveSettings: (next) => {
      settings = next;
      applyQuality(renderer, next.quality);
      audio?.setMasterVolume(volumeToGain(next.volume));
      game?.setControlScheme(next.controlScheme);
      game?.setQuality(next.quality);
      game?.setVolume(next.volume);
    },
  },
  { initialCourseId: selection.course.id },
);

const resize = (): void => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
};
window.addEventListener('resize', resize);

let lastFrame = performance.now();
renderer.setAnimationLoop(() => {
  const now = performance.now();
  const dt = Math.min(0.05, Math.max(0, (now - lastFrame) / 1000));
  lastFrame = now;
  game?.frame(dt);
  renderer.render(game ? game.scene : menuScene, camera);
  diagnostics?.frame();
  input.endFrame();
});

// Debug launches skip the menu and drop straight into the resolved course/hole.
if (launch.debug) {
  void import('./dev').then(async ({ DeveloperDiagnostics }) => {
    document.documentElement.dataset.debug = '1';
    if (launch.courseId) document.documentElement.dataset.debugCourse = launch.courseId;
    if (launch.hole) document.documentElement.dataset.debugHole = String(launch.hole);
    await startMatch(
      { players: 1, bots: 3, holes: 9, courseId: selection.course.id },
      selection.holeIndex,
    );
    diagnostics = new DeveloperDiagnostics({
      root,
      renderer: renderer.renderer,
      scene: game ? game.scene : menuScene,
      camera,
    });
  });
}

window.addEventListener(
  'pagehide',
  () => {
    renderer.setAnimationLoop(null);
    game?.dispose();
    game = undefined;
    input.dispose();
    diagnostics?.dispose();
    audio?.dispose();
    renderer.dispose();
  },
  { once: true },
);
EOF
